import unittest
from candidate import flip_case

class TestFlipCase(unittest.TestCase):
    def test_flip_case_normal_string(self):
        self.assertEqual(flip_case('Hello'), 'hELLO')

    def test_flip_case_all_uppercase(self):
        self.assertEqual(flip_case('HELLO'), 'hello')

    def test_flip_case_all_lowercase(self):
        self.assertEqual(flip_case('hello'), 'HELLO')

    def test_flip_case_mixed_case(self):
        self.assertEqual(flip_case('HeLlO'), 'hElLo')

    def test_flip_case_empty_string(self):
        self.assertEqual(flip_case(''), '')

    def test_flip_case_single_character(self):
        self.assertEqual(flip_case('a'), 'A')

    def test_flip_case_single_uppercase_character(self):
        self.assertEqual(flip_case('A'), 'a')

    def test_flip_case_none_input(self):
        with self.assertRaises(TypeError):
            flip_case(None)

    def test_flip_case_non_string_input(self):
        with self.assertRaises(TypeError):
            flip_case(123)

if __name__ == '__main__':
    unittest.main()
